create policy programs_update on public.programs for update to authenticated using (app.can_write() and (app.sees_div(div) or owner = app.me_id() or created_by = app.me_id() or exists (select 1 from jsonb_array_elements(coalesce(doc::jsonb->'partners', '[]'::jsonb)) x where x->>'state' = 'joined' and app.sees_div(x->>'div')))) with check (app.can_write() and (app.sees_div(div) or owner = app.me_id() or created_by = app.me_id() or exists (select 1 from jsonb_array_elements(coalesce(doc::jsonb->'partners', '[]'::jsonb)) x where x->>'state' = 'joined' and app.sees_div(x->>'div'))));
create policy programs_delete on public.programs for delete to authenticated using (app.can_write() and (app.sees_div(div) or owner = app.me_id() or created_by = app.me_id() or exists (select 1 from jsonb_array_elements(coalesce(doc::jsonb->'partners', '[]'::jsonb)) x where x->>'state' = 'joined' and app.sees_div(x->>'div'))));
grant select, insert, update, delete on public.programs to authenticated, service_role;

-- routines  <-  db.routines
create table public.routines (
  id text primary key,
  pos integer not null default 0,
  doc json not null,
  unit text generated always as (doc->>'unit') stored,
  personal boolean generated always as ((doc->>'personal')::boolean) stored,
  project text generated always as (doc->>'project') stored,
  created_by text generated always as (doc->>'createdBy') stored,
  program text generated always as (doc->>'program') stored,
  updated_at timestamptz not null default now(),
  updated_by uuid,
  constraint routines_id_matches_doc check (doc->>'id' is null or doc->>'id' = id)
);
create index routines_unit_idx on public.routines (unit);
create index routines_project_idx on public.routines (project);
create index routines_created_by_idx on public.routines (created_by);
create index routines_program_idx on public.routines (program);
create trigger routines_touch before update on public.routines for each row execute function app.touch();
alter table public.routines enable row level security;
create policy routines_select on public.routines for select to authenticated using (app.me_active() and (case when coalesce(personal, false) then (jsonb_exists(doc::jsonb->'owners', app.me_id()) or created_by = app.me_id()) else (app.sees_div(unit) or jsonb_exists(doc::jsonb->'owners', app.me_id())) end));
create policy routines_insert on public.routines for insert to authenticated with check (app.can_write() and (case when coalesce(personal, false) then (jsonb_exists(doc::jsonb->'owners', app.me_id()) or created_by = app.me_id()) else (app.sees_div(unit) or jsonb_exists(doc::jsonb->'owners', app.me_id())) end));
create policy routines_update on public.routines for update to authenticated using (app.can_write() and (case when coalesce(personal, false) then (jsonb_exists(doc::jsonb->'owners', app.me_id()) or created_by = app.me_id()) else (app.sees_div(unit) or jsonb_exists(doc::jsonb->'owners', app.me_id())) end)) with check (app.can_write() and (case when coalesce(personal, false) then (jsonb_exists(doc::jsonb->'owners', app.me_id()) or created_by = app.me_id()) else (app.sees_div(unit) or jsonb_exists(doc::jsonb->'owners', app.me_id())) end));
create policy routines_delete on public.routines for delete to authenticated using (app.can_write() and (case when coalesce(personal, false) then (jsonb_exists(doc::jsonb->'owners', app.me_id()) or created_by = app.me_id()) else (app.sees_div(unit) or jsonb_exists(doc::jsonb->'owners', app.me_id())) end));
grant select, insert, update, delete on public.routines to authenticated, service_role;

-- pins  <-  db.pins (object keyed by id)
create table public.pins (
  id text primary key,
