alter table public.pins enable row level security;
create policy pins_select on public.pins for select to authenticated using (app.me_active() and (id = app.me_id()));
create policy pins_insert on public.pins for insert to authenticated with check (app.can_write() and (id = app.me_id()));
create policy pins_update on public.pins for update to authenticated using (app.can_write() and (id = app.me_id())) with check (app.can_write() and (id = app.me_id()));
create policy pins_delete on public.pins for delete to authenticated using (app.can_write() and (id = app.me_id()));
grant select, insert, update, delete on public.pins to authenticated, service_role;

