create policy acct_invites_update on public.acct_invites for update to authenticated using (app.can_write() and (not app.is_board() and (app.me_admin() or app.hr_lead() or lower(email) = app.me_email()))) with check (app.can_write() and (not app.is_board() and (app.me_admin() or app.hr_lead() or lower(email) = app.me_email())));
